tasks.named("assemble").configure { enabled = false }
base {
  archivesName = 'elasticsearch-benchmarks'
}

tasks.named("javadoc").configure { enabled = false }

versions << [
  'hadoop': '3.4.3',
]

configurations {
  expression
  painless
  nativeLib
}

dependencies {
  api(project(":server")) {
    // JMH ships with the conflicting version 4.6. This prevents us from using jopt-simple in benchmarks (which should be ok) but allows
    // us to invoke the JMH uberjar as usual.
    exclude group: 'net.sf.jopt-simple', module: 'jopt-simple'
  }
  api(project(':libs:h3'))
  api(project(':modules:aggregations'))
  implementation project(':modules:mapper-extras');
  api(project(':x-pack:plugin:esql-core'))
  api(project(':x-pack:plugin:core'))
  api(project(':x-pack:plugin:esql'))
  api(project(':x-pack:plugin:esql:compute'))
  api(project(':x-pack:plugin:esql:qa:testFixtures'))
  api(project(':x-pack:plugin:esql-datasource-csv'))
  api(project(':x-pack:plugin:esql-datasource-gzip'))
  api(project(':x-pack:plugin:esql-datasource-parquet'))
  api(project(':x-pack:plugin:esql-datasource-orc'))
  api(project(':x-pack:plugin:esql-datasource-ndjson'))
  // DissectParser for FlattenedFieldExtractBenchmark's `dissect` consumer; esql exposes grok transitively
  // but keeps dissect as an `implementation` dep, so it is not on the benchmark compile classpath otherwise.
  implementation project(':libs:dissect')
  // Writer-side dependencies for in-memory Parquet/ORC fixtures used by the format-reader
  // JMH benchmarks. The plugin projects above expose the reader classes only; the writers
  // (ExampleParquetWriter, OrcFile.createWriter) live in the underlying third-party jars
  // which the plugins declare as `implementation` (not propagated to consumers). These are
  // benchmark-only deps; they never end up in a shipped artifact.
  implementation "org.apache.parquet:parquet-hadoop-bundle:${versions.parquet}"
  implementation "org.apache.orc:orc-core:${versions.orc}"
  implementation 'org.apache.hive:hive-storage-api:2.8.1'
  implementation("org.apache.hadoop:hadoop-common:${versions.hadoop}") { transitive = false }

  // parquet-hadoop-bundle transitively brings in hadoop-client-api and
  // hadoop-client-runtime, which ship the same classes (e.g. org.apache.hadoop.ipc.RPC$RpcKind)
  // as the hadoop-common jar we declare above for the ORC writer's RawLocalFileSystem path.
  // The two layouts collide at *runtime* and trigger ESTestCase's JarHell check, but we
  // still need hadoop-client-api at *compile* time because it provides
  // org.apache.hadoop.classification.InterfaceAudience (referenced by Configuration's
  // public-API annotations). Exclude only from runtime — let hadoop-common provide the
  // hadoop API surface at runtime; parquet's PlainParquetConfiguration / PlainCompressionCodecFactory
  // bypass the Hadoop-dependent paths so the bundle never needs the client jars at runtime.
  ['runtimeClasspath', 'testRuntimeClasspath'].each { c ->
    configurations.named(c).configure {
      exclude group: 'org.apache.hadoop', module: 'hadoop-client-api'
      exclude group: 'org.apache.hadoop', module: 'hadoop-client-runtime'
    }
  }
  api(project(':x-pack:plugin:analytics'))
  api(project(':x-pack:plugin:logsdb'))
  implementation project(path: ':libs:native')
  implementation project(path: ':libs:simdvec')
  implementation project(path: ':libs:columnar')
  implementation (testFixtures(project(path: ':libs:simdvec')))
  implementation project(path: ':libs:exponential-histogram')
  implementation(project(':x-pack:plugin:searchable-snapshots')) {
    capabilities {
      requireCapability("org.elasticsearch.plugin:searchable-snapshots-test-artifacts")
    }
  }
  implementation project(':x-pack:plugin:blob-cache')
  implementation project(':x-pack:plugin:stateless')
  implementation(project(':x-pack:plugin:stateless')) {
    capabilities {
      requireCapability("org.elasticsearch.plugin:stateless-test-artifacts")
    }
  }
  expression(project(path: ':modules:lang-expression', configuration: 'zip'))
  painless(project(path: ':modules:lang-painless', configuration: 'zip'))
  nativeLib(project(':libs:native'))
  implementation project(':modules:bitmap')
  implementation("org.roaringbitmap:RoaringBitmap:1.6.15")
  // Shared benchmark helpers (Utils, ExtraParam) plus the log4j LoggerFactory bootstrap
  // and the BenchmarkConfigurationFactory that strips %node_name / %cluster_name from
  // any .properties log4j config on the classpath. See benchmarks/common/build.gradle.
  implementation project(':benchmarks:common')
  api "org.openjdk.jmh:jmh-core:$versions.jmh"
  annotationProcessor "org.openjdk.jmh:jmh-generator-annprocess:$versions.jmh"
  annotationProcessor project(':benchmarks:processor')
  // Dependencies of JMH
  runtimeOnly "net.sf.jopt-simple:jopt-simple:${versions.jopt_simple}"
  runtimeOnly "org.apache.commons:commons-math3:${versions.commons_math3}"

  testImplementation(project(':test:framework'))
}

// enable the JMH's BenchmarkProcessor to generate the final benchmark classes
// needs to be added separately otherwise Gradle will quote it and javac will fail
tasks.named("compileJava").configure {
  options.compilerArgs.addAll(["-processor", "org.openjdk.jmh.generators.BenchmarkProcessor,org.elasticsearch.benchmark.ExtraParamProcessor"])
  // org.elasticsearch.plugins.internal is used in signatures classes used in benchmarks but we don't want to expose it publicly
  // adding an export to allow compilation with gradle. This does not solve a problem in intellij as it does not use compileJava task
  options.compilerArgs.addAll(["--add-exports", "org.elasticsearch.server/org.elasticsearch.plugins.internal=ALL-UNNAMED"])
}

tasks.register('copyExpression', Copy) {
  dependsOn configurations.expression
  from { configurations.expression.collect { zipTree(it) } }
  into "${buildDir}/plugins/expression"
}

tasks.register("copyPainless", Copy) {
  dependsOn configurations.painless
  from { configurations.painless.collect { zipTree(it) } }
  into "${buildDir}/plugins/painless"
}

tasks.named("run").configure {
  executable = "${buildParams.runtimeJavaHome.get()}/bin/java" + (OS.current() == OS.WINDOWS ? '.exe' : '')
  dependsOn "copyExpression", "copyPainless", configurations.nativeLib, ":libs:native:native-libraries:extractLibs"
  systemProperty 'plugins.dir', "${buildDir}/plugins"
  systemProperty 'tests.index', "${buildDir}/index"
  def nativeLibsPath = TestUtil.getTestLibraryPath(file("../libs/native/libraries/build/platform/").toString())
  systemProperty 'es.nativelibs.path', nativeLibsPath
  // Arrow's MemoryUtil reflects into java.nio.Buffer.address during static init; the parquet
  // format reader transitively triggers this via BlockFactory.arrowAllocator(). Mirrors the
  // flag already set on the test task above and on :x-pack:plugin:esql-datasource-parquet:test.
  jvmArgs '--add-opens=java.base/java.nio=ALL-UNNAMED'
  jvmArgs '--enable-native-access=ALL-UNNAMED'
  jvmArgs '-Dorg.apache.lucene.vectorization.upperJavaFeatureVersion=' + buildParams.getRuntimeJavaVersion().map { it.majorVersion }.get()
  // Without this the vectorization providers fall back to their scalar implementations, so a benchmark
  // over vectorized code measures something the product never runs. Needed on the forked VMs, which are
  // where the benchmark bodies execute, as well as on the harness that runs them.
  def vectorArgs = buildParams.getRuntimeJavaVersion().map { it.majorVersion.toInteger() }.get() >= 21
    ? ' --add-modules=jdk.incubator.vector'
    : ''
  if (vectorArgs) {
    jvmArgs '--add-modules=jdk.incubator.vector'
  }
  // Forward es.nativelibs.path to JMH forked VMs via default jvmArgsAppend
  args '-jvmArgsAppend', "-Des.nativelibs.path=${nativeLibsPath}${vectorArgs}"
}

tasks.named('test').configure {
  if (buildParams.getRuntimeJavaVersion().map{ it.majorVersion.toInteger() }.get() >= 21) {
    jvmArgs '--add-modules=jdk.incubator.vector', '--add-opens=java.base/java.nio=ALL-UNNAMED'
  }
}

spotless {
  java {
    // IDEs can sometimes run annotation processors that leave files in
    // here, causing Spotless to complain. Even though this path ought not
    // to exist, exclude it anyway in order to avoid spurious failures.
    targetExclude 'src/main/generated/**/*.java'
  }
}

