tasks.named('test').configure {
  useJUnitPlatform()
}
tasks.register("archunitTest", Test) {
  dependsOn("testClasses", "integTestClasses")
  testClassesDirs = sourceSets.archunit.output.classesDirs
  classpath = sourceSets.archunit.runtimeClasspath
  useJUnitPlatform()
}
tasks.register("integTest", Test) {
  systemProperty 'test.version_under_test', version
  testClassesDirs = sourceSets.integTest.output.classesDirs
  classpath = sourceSets.integTest.runtimeClasspath
  useJUnitPlatform()
  // ElasticsearchTestBasePlugin cannot apply itself, so java.io.tmpdir must be set manually here.
  // Without it, JUnit/Spock create temp dirs under /tmp (root fs) instead of the build dir (/dev/shm in CI).
  // The nested Gradle TestKit runners require an absolute path, so a relative value is not an option here.
  // A CommandLineArgumentProvider keeps that absolute path out of the task inputs so it stays cache relocatable.
  def tempDir = temporaryDir
  // Pin the TestKit root instead of letting TestKit derive it from java.io.tmpdir, so that
  // AbstractGradleFuncTest can lay out one Gradle user home per worker below it.
  def testKitDir = new File(temporaryDir, ".gradle-test-kit")
  jvmArgumentProviders.add({
    ["-Djava.io.tmpdir=${tempDir}", "-Dorg.gradle.testkit.dir=${testKitDir}"] as List<String>
  } as CommandLineArgumentProvider)
}

tasks.named("check").configure { dependsOn("integTest", "archunitTest") }

tasks.register("bootstrapPerformanceTests", Copy) {
  from('performance')
  into('build/performanceTests')
  def root = file('..')
  inputs.property('branchWrapper', gradle.gradleVersion)
  filter(ReplaceTokens, tokens: [
          testGitCommit:GitInfo.gitInfo(root).revision,
          mainWrapper:"${ -> resolveMainWrapperVersion()}".toString(),
          branchWrapper:"${-> gradle.gradleVersion}".toString()])
}

tasks.named("jar") {
  exclude("classpath.index")
}

spotless {
  java {

    // workaround for https://github.com/diffplug/spotless/issues/2317
    //toggleOffOn()
    target project.fileTree("src/main/java") {
      include '**/*.java'
      exclude '**/DockerBase.java'
    }
  }
}

def resolveMainWrapperVersion() {
  new URL("https://raw.githubusercontent.com/elastic/elasticsearch/main/build-tools-internal/src/main/resources/minimumGradleVersion").text.trim()
}

abstract class JacksonAlignmentRule implements ComponentMetadataRule {
  void execute(ComponentMetadataContext ctx) {
    ctx.details.with {d ->
      // jackson-annotations is released without a patch version (e.g. 2.21), so aligning it would
      // put it on a different jackson-bom version than the other modules and conflict with the enforced platform
      if (d.id.group.startsWith("com.fasterxml.jackson") && d.id.name != "jackson-annotations") {
        // declare that Jackson modules all belong to the Jackson virtual platform
        belongsTo("com.fasterxml.jackson:jackson-bom:${d.id.version}")
      }
    }
  }
}

