def getTargetPlatforms() {
    String arch = selectArch()
    if (arch == "x86_64") {
        return [[os: "linux", arch: "x86_64"], [os: "windows", arch: "x86_64"], [os: "darwin", arch: "x86_64"]]
    } else {
        return [[os: "linux", arch: "arm64"], [os: "darwin", arch: "arm64"]]
    }
}

["linux", "windows", "darwin"].each { osName ->
    ["x86_64", "arm64"].each { archName ->
        if (osName == "windows" && archName == "arm64") { return }
        String taskSuffix = "${osName.capitalize()}${archName == 'x86_64' ? 'X64' : 'Arm64'}"
        String jdkFolderName = ToolingUtils.jdkFolderName(osName, archName)

        tasks.register("downloadJdk${taskSuffix}", Download) {
            def jdkDetails = new JDKDetails(gradle.ext.versions.bundled_jdk, osName, archName)
            // Use provider for lazy evaluation - only resolve URL when task executes
            src provider { System.getenv("JDK_URL") ?: jdkDetails.createDownloadUrl() }
            onlyIfNewer true
            overwrite false
            retries 3
            quiet true
            inputs.file("${projectDir}/versions.yml")
            dest new File("${projectDir}/build/${jdkDetails.localPackageName}")
            doFirst { mkdir "${projectDir}/${jdkFolderName}" }
        }

        if (osName == "windows") {
            tasks.register("unpackJdk${taskSuffix}", Copy) {
                dependsOn "downloadJdk${taskSuffix}"
                def jdkDetails = new JDKDetails(gradle.ext.versions.bundled_jdk, osName, archName)
                String rootName = null
                from(zipTree("${projectDir}/build/${jdkDetails.localPackageName}")) {
                    eachFile { fcd ->
                        rootName = rootName ?: fcd.relativePath.segments[0]
                        fcd.relativePath = new RelativePath(true, fcd.relativePath.segments.drop(1))
                    }
                }
                into "${projectDir}/${jdkFolderName}"
                doLast { delete "${projectDir}/${jdkFolderName}/$rootName" }
            }
        } else {
            tasks.register("unpackJdk${taskSuffix}", Exec) {
                dependsOn "downloadJdk${taskSuffix}"
                def jdkDetails = new JDKDetails(gradle.ext.versions.bundled_jdk, osName, archName)
                commandLine 'tar', 'xf', "${projectDir}/build/${jdkDetails.localPackageName}", '-C', "${projectDir}/${jdkFolderName}", '--strip-components', '1'
                doFirst { mkdir "${projectDir}/${jdkFolderName}" }
            }
        }
    }
}

