    maxHeapSize = '1500m'
    systemProperty 'java.awt.headless', true
    // Some tests are asserting on localized messages or dates
    systemProperty 'user.language', 'en'
    systemProperty 'user.country', 'US'
    environment 'LANGUAGE', 'en_US'
    testLogging {
      events "skipped", "failed" // verbose log for failed and skipped tests (by default the name of the tests are not logged)
      exceptionFormat 'full' // log the full stack trace (default is the 1st line of the stack trace)
    }
    jacoco {
      enabled = true // do not disable recording of code coverage, so that remote Gradle cache entry can be used locally
      includes = ['com.sonar.*', 'com.sonarsource.*', 'org.sonar.*', 'org.sonarqube.*', 'org.sonarsource.*']
    }
    if (project.hasProperty('maxParallelTests')) {
      maxParallelForks = project.maxParallelTests as int
    }
    if (project.hasProperty('parallelTests')) {
      // See https://guides.gradle.org/performance/#parallel_test_execution
      maxParallelForks = Runtime.runtime.availableProcessors().intdiv(2) ?: 1
    }

    afterTest { descriptor, result ->
      if (result.resultType == TestResult.ResultType.FAILURE) {
        String failedTest = "  ${descriptor.className} > ${descriptor.name}"
        failedTests << failedTest
      }
    }
  }

  gradle.buildFinished {
    if (!failedTests.empty) {
      println "\nFailed tests:"
      failedTests.each { failedTest ->
        println failedTest
      }
      println ""
    }
  }

  // Route tests by @Tag("elasticsearch") / @Category(ElasticsearchTest.class) rather than by module.
  // -PexcludeElasticsearchTests → junit CI job (no ES cluster needed)
  // -PincludeElasticsearchTests → es-junit CI job (requires live ES cluster)
  // Neither property → all tests run (default for local/IDE runs)
  if (project.hasProperty('excludeElasticsearchTests') || project.hasProperty('includeElasticsearchTests')) {
    afterEvaluate {
      tasks.withType(Test).configureEach { testTask ->
        if (testTask.options instanceof org.gradle.api.tasks.testing.junitplatform.JUnitPlatformOptions) {
          def platformOptions = testTask.options as org.gradle.api.tasks.testing.junitplatform.JUnitPlatformOptions
          if (project.hasProperty('excludeElasticsearchTests')) {
            platformOptions.excludeTags.addAll(['elasticsearch', 'org.sonar.test.tags.ElasticsearchTest'])
          } else if (project.hasProperty('includeElasticsearchTests')) {
            platformOptions.includeTags.addAll(['elasticsearch', 'org.sonar.test.tags.ElasticsearchTest'])
          }
        } else if (project.hasProperty('includeElasticsearchTests')) {
