  // Delimiter regex matches the first line that is NOT part of a `/* ... */` license header
  // (rejects the literal `/*` opener line, ` *` body/closer lines, and blank lines).
  // This preserves any content between the header and the first code line, e.g. JSDoc, eslint-disable
  // directives, secondary `//` attribution blocks.
  def headerDelimiter = '(?m)^(?!/\\*\\s*$| \\*|\\s*$).+'

