      targetExclude 'build/**', 'node_modules/**'
      licenseHeaderFile headerFile, headerDelimiter
    }
    format 'typescript', {
      target 'src/**/*.ts', 'src/**/*.tsx'
      targetExclude 'build/**', 'node_modules/**'
      licenseHeaderFile headerFile, headerDelimiter
